def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 > v2:
        result = 2018
    elif v2 > v1:
        result = 2017
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "v1_2018": v1,
            "v2_2017": v2,
            "comparison": "2018 > 2017" if v1 > v2 else "2017 > 2018" if v2 > v1 else "equal",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
